-- One commission statement per immutable contractual recipient, even within one day.
-- The preview checkpoint binds all pending source events. Issuance is atomic across groups.
create function private.provider_statement_recipient_groups_v1(p_organization_id uuid,p_period_start date,p_period_end date,p_currency char(3))returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private as $$
declare groups jsonb;checkpoint jsonb;invalid boolean;begin
 with pending as materialized(select e.id,e.contract_version_id,e.commission_amount_minor,e.tax_amount_minor,e.total_due_minor from public.provider_payable_events e where e.provider_organization_id=p_organization_id and e.currency=p_currency and e.occurred_on between p_period_start and p_period_end and not exists(select 1 from public.provider_statement_lines l where l.payable_event_id=e.id)),
 identities as materialized(select version_id,private.provider_contract_recipient_snapshot_v1(version_id)recipient from(select distinct contract_version_id version_id from pending)versions),
 enriched as materialized(select pending.*,identities.recipient,case when identities.recipient is null then null else private.canonical_request_hash(identities.recipient)end recipient_hash from pending join identities on identities.version_id=pending.contract_version_id),
 grouped as(select recipient_hash,recipient,jsonb_agg(id order by id)event_ids,count(*)event_count,sum(commission_amount_minor)::text subtotal_minor,sum(tax_amount_minor)::text tax_minor,sum(total_due_minor)::text total_minor from enriched group by recipient_hash,recipient)
 select coalesce((select jsonb_agg(to_jsonb(grouped)order by recipient_hash)from grouped),'[]'),coalesce((select bool_or(recipient is null)from enriched),false),coalesce((select jsonb_agg(jsonb_build_object('id',id,'contract_version_id',contract_version_id,'recipient_hash',recipient_hash,'net',commission_amount_minor::text,'tax',tax_amount_minor::text)order by id)from enriched),'[]')into groups,invalid,checkpoint;
 if invalid then raise exception'BILLING_CONTRACT_RECIPIENT_REVIEW_REQUIRED'using errcode='55000';end if;
 return jsonb_build_object('source_hash',private.canonical_request_hash(jsonb_build_object('organization_id',p_organization_id,'period_start',p_period_start,'period_end',p_period_end,'currency',p_currency,'events',checkpoint)),'groups',groups);
end$$;
revoke all on function private.provider_statement_recipient_groups_v1(uuid,date,date,character)from public,anon,authenticated,service_role;
create function public.preview_provider_grouped_statements_v1(p_provider_organization_id uuid,p_period_start date,p_period_end date,p_currency char(3))returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private as $$begin
 if not private.provider_billing_write_access(p_provider_organization_id,auth.uid())then raise exception'PROVIDER_STATEMENT_DENIED'using errcode='42501';end if;
 if p_period_start is null or p_period_end is null or p_period_end<p_period_start or p_currency is null or p_currency!~'^[A-Z]{3}$'then raise exception'INVALID_STATEMENT_PERIOD'using errcode='22023';end if;
 return private.provider_statement_recipient_groups_v1(p_provider_organization_id,p_period_start,p_period_end,p_currency);
end$$;
create function public.issue_provider_grouped_statements_v1(p_provider_organization_id uuid,p_number_prefix text,p_period_start date,p_period_end date,p_currency char(3),p_expected_source_hash text,p_idempotency_key uuid,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare source jsonb;group_item jsonb;policy jsonb;response jsonb;command_hash text;document_hash text;statements jsonb:='[]';statement_id uuid;number text;sequence integer:=0;issued date:=(clock_timestamp()at time zone'Africa/Casablanca')::date;begin
 if not private.provider_billing_write_access(p_provider_organization_id,auth.uid())then raise exception'PROVIDER_STATEMENT_DENIED'using errcode='42501';end if;
 if p_period_start is null or p_period_end is null or p_period_end<p_period_start or p_currency is null or p_currency!~'^[A-Z]{3}$'or p_number_prefix is null or length(btrim(p_number_prefix))not between 3 and 55 or p_expected_source_hash is null or p_expected_source_hash!~'^[0-9a-f]{64}$'or p_idempotency_key is null then raise exception'INVALID_GROUPED_STATEMENT'using errcode='22023';end if;
 command_hash:=private.canonical_request_hash(jsonb_build_object('organization_id',p_provider_organization_id,'prefix',btrim(p_number_prefix),'start',p_period_start,'end',p_period_end,'currency',p_currency,'source_hash',p_expected_source_hash));
 response:=private.begin_provider_billing_command(p_provider_organization_id,'provider.billing.grouped_statement.issue',p_idempotency_key::text,command_hash,auth.uid());if response is not null then return response;end if;
 perform pg_advisory_xact_lock(hashtextextended(p_provider_organization_id::text||':'||p_currency::text||':provider-statement',0));
 source:=private.provider_statement_recipient_groups_v1(p_provider_organization_id,p_period_start,p_period_end,p_currency);
 if source->>'source_hash'is distinct from p_expected_source_hash then raise exception'BILLING_GROUPED_STATEMENT_SOURCE_CHANGED'using errcode='40001';end if;
 if jsonb_array_length(source->'groups')=0 then raise exception'NO_UNSTATEMENTED_PAYABLES'using errcode='P0002';end if;
 policy:=private.approved_billing_policy_snapshot(p_currency,issued);if policy is null then raise exception'BILLING_POLICY_REQUIRED'using errcode='55000';end if;
 for group_item in select value from jsonb_array_elements(source->'groups')loop
  sequence:=sequence+1;number:=btrim(p_number_prefix)||'-G'||lpad(sequence::text,4,'0');statement_id:=extensions.gen_random_uuid();
  if(group_item->>'total_minor')::bigint<=0 then raise exception'INVALID_GROUPED_STATEMENT_TOTAL'using errcode='23514';end if;
  document_hash:=private.canonical_request_hash(jsonb_build_object('command_hash',command_hash,'number',number,'group',group_item,'policy_id',policy->>'policy_id'));
  insert into public.provider_statements(id,provider_organization_id,statement_number,period_start,period_end,currency,subtotal_minor,tax_minor,total_minor,document_hash,correlation_id,created_by)values(statement_id,p_provider_organization_id,number,p_period_start,p_period_end,p_currency,(group_item->>'subtotal_minor')::bigint,(group_item->>'tax_minor')::bigint,(group_item->>'total_minor')::bigint,document_hash,p_correlation_id,auth.uid());
  insert into public.provider_statement_lines(provider_organization_id,statement_id,payable_event_id,subtotal_minor,tax_minor,total_minor)select p_provider_organization_id,statement_id,e.id,e.commission_amount_minor,e.tax_amount_minor,e.total_due_minor from public.provider_payable_events e where e.provider_organization_id=p_provider_organization_id and e.id in(select value::uuid from jsonb_array_elements_text(group_item->'event_ids'));
  insert into public.provider_billing_source_policy_bindings(provider_organization_id,kind,source_id,source_hash,policy_id,policy_snapshot,document_number,issued_on,bound_by)values(p_provider_organization_id,'statement',statement_id,document_hash,(policy->>'policy_id')::uuid,policy||jsonb_build_object('recipient_snapshot',group_item->'recipient'),number,issued,auth.uid());
  response:=jsonb_build_object('statement_id',statement_id,'statement_number',number,'recipient',group_item->'recipient','total_minor',group_item->>'total_minor','currency',p_currency,'document_status','EDITION_PENDING');statements:=statements||jsonb_build_array(response);
  insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_provider_organization_id,auth.uid(),'USER','provider.statement.grouped_issued','provider_statement',statement_id::text,p_correlation_id,jsonb_build_object('source_hash',p_expected_source_hash,'recipient_hash',group_item->>'recipient_hash','source_event_count',group_item->'event_count'),repeat('0',64));
  insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_provider_organization_id,'provider_statement',statement_id::text,'ProviderStatementIssuedV1',p_correlation_id,jsonb_build_object('statement_id',statement_id),'provider-grouped-statement:'||p_idempotency_key::text||':'||sequence::text);
 end loop;
 response:=jsonb_build_object('outcome','PROVIDER_GROUPED_STATEMENTS_ISSUED','statements',statements);perform private.finish_provider_billing_command(p_provider_organization_id,'provider.billing.grouped_statement.issue',p_idempotency_key::text,response);return response;
end$$;
revoke all on function public.preview_provider_grouped_statements_v1(uuid,date,date,character),public.issue_provider_grouped_statements_v1(uuid,text,date,date,character,text,uuid,uuid)from public,anon,service_role;
grant execute on function public.preview_provider_grouped_statements_v1(uuid,date,date,character),public.issue_provider_grouped_statements_v1(uuid,text,date,date,character,text,uuid,uuid)to authenticated;
notify pgrst,'reload schema';
